def _measured_inputs_key(self) -> Tuple[Any, ...]:
    return tuple((key, self.counter_values[key])
                 for key in sorted(self.counter_values))

def _demands_key(self) -> Tuple[Any, ...]:
    return tuple((s, d, self.demands[(s, d)])
                 for s, d in self.demand_pairs)

def _routes_key(self) -> Any:
    if not self.has_routes:
        return None
    # path entries are already canonicalized (multiset semantics).
    assert self.route_lookup is not None
    return tuple(sorted(
        (s, d, paths)
        for (s, d), paths in self.route_lookup.items()
    ))

def _cache_key(self) -> Tuple[Any, ...]:
    return (
        self._topology_key(),
        self._measured_inputs_key(),
        self._demands_key(),
        self._routes_key(),
        (self.seed, self.trials, self.epsilon),
    )

